{
  "name": "agent-reflex",
  "version": "0.1.0",
  "description": "OpenCode plugin for coding agent workflow optimization and safeguarding using any System One decision model, from Jev to self-hosted LM Studio, Ollama or llama.cpp.",
  "type": "module",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/psygreg/agent-reflex.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "system-one",
    "decision-model",
    "jev",
    "coding-agent"
  ],
  "exports": {
    ".": "./plugins/opencode/index.ts"
  },
  "files": [
    "plugins/opencode",
    ".agents/skills/agent-reflex",
    "install.sh",
    "opencode.example.jsonc",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "check": "tsc --noEmit"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2"
  },
  "devDependencies": {
    "@opencode/plugin": "latest",
    "bun-types": "latest",
    "typescript": "latest"
  }
}
